text:
{
  "status": "AUTHORIZED_UNIQUE",
  "coverage": [
    {
      "text": "往前挪",
      "role": "ACTION",
      "explanation": "请求向前移动；在合法 Mission IR 动作中对应 walk_forward，而不是 turn、stand 或 stop。"
    },
    {
      "text": "4米",
      "role": "QUANTITY",
      "explanation": "给出 walk_forward 的正有限距离参数，即 distance_m=4 米；米为合法单位。"
    },
    {
      "text": "就行",
      "role": "CONTEXT",
      "explanation": "口语化结束/足够标记，本身不请求任何动作，也不添加 stop。"
    },
    {
      "text": "。",
      "role": "SEPARATOR",
      "explanation": "句末标点，仅分隔前后句，不改变动作或关系。"
    },
    {
      "text": "‘就行’",
      "role": "CONTEXT",
      "explanation": "引用前一句中的“就行”，为后续澄清限定作用对象；不新增动作。"
    },
    {
      "text": "只是我说完了，",
      "role": "EDIT",
      "explanation": "明确限定“就行”的含义仅为说话结束，不表示添加停或改变先前的前进动作。"
    },
    {
      "text": "不另加停。",
      "role": "EDIT",
      "explanation": "显式排除额外添加 stop；这是否定性澄清，不产生 stop 动作。"
    }
  ],
  "dimensions": {
    "action_multiplicity": {
      "status": "UNIQUE",
      "explanation": "唯一动作请求是“往前挪4米”，对应一个 walk_forward；“就行”是结束标记，“不另加停”是否定澄清，均不增加 stand、turn 或 stop。"
    },
    "action_order": {
      "status": "UNIQUE",
      "explanation": "源中只有一个动作，因此不存在多个执行顺序、先后或同时关系需要选择；线性计划只能是单个 walk_forward 步骤。"
    },
    "correction_scope": {
      "status": "UNIQUE",
      "explanation": "第二句明确限定“就行”的范围：它只表示说话结束，不添加 stop，并保留前面的前进距离动作，不替换或修改其距离。"
    },
    "repetition_scope": {
      "status": "UNIQUE",
      "explanation": "没有重复执行动作的请求；“4米”是单一距离，引号中的“就行”只是被澄清的引用，不构成重复命令或重复动作。"
    },
    "reference_resolution": {
      "status": "UNIQUE",
      "explanation": "“往前挪”唯一解析为向前 walk_forward；“‘就行’”指前句“就行”；“不另加停”指不向该请求添加 stop，无未解决指代或序数引用。"
    },
    "temporal_relations": {
      "status": "UNIQUE",
      "explanation": "没有 before/after、同时、等待或完成关系；单一步骤可直接线性化为 s1: walk_forward 4m，无需发明时间关系。"
    },
    "unresolved_relations": {
      "status": "UNIQUE",
      "explanation": "源中没有明确未解决的选择、范围、顺序或关系；唯一可能含糊的“就行”已被后续澄清为不添加 stop。"
    }
  }
}
